reference.setup:
{
    groups_of <- function(...) lapply(list(...), function(x) x[!is.na(x)])
    kruskal <- function(groups, comps = "all", control = 1, corrected = TRUE) {
        k <- length(groups)
        n <- lengths(groups)
        y <- unlist(groups)
        g <- rep(seq_len(k), n)
        kt <- kruskal.test(groups)
        r <- rank(y)
        rs <- tapply(r, g, sum)
        out <- list(k = k, n_total = length(y), h = unname(kt$statistic), df = unname(kt$parameter), 
            p = kt$p.value, groups = lapply(seq_len(k), function(i) {
                list(n = n[i], median = median(groups[[i]]), rank_sum = rs[[i]], 
                  mean_rank = rs[[i]]/n[i])
            }))
        out$comparisons <- if (comps == "none") 
            list()
        else {
            N <- length(y)
            t <- table(y)
            pairs <- unname(if (comps == "all") {
                do.call(rbind, lapply(seq_len(k - 1), function(i) cbind(i, (i + 1):k)))
            }
            else {
                cbind(control, seq_len(k)[-control])
            })
            K <- nrow(pairs)
            lapply(seq_len(K), function(x) {
                i <- pairs[x, 1]
                j <- pairs[x, 2]
                d <- rs[[i]]/n[i] - rs[[j]]/n[j]
                se <- sqrt((N * (N + 1) - sum(t^3 - t)/(N - 1))/12 * (1/n[i] + 1/n[j]))
                z <- abs(d)/se
                p <- 2 * pnorm(z, lower.tail = FALSE)
                list(i = i, j = j, diff = d, z = z, p_unadjusted = p, p = if (corrected) min(1, 
                  K * p) else p)
            })
        }
        out
    }
}
